def taller_within(a: list[int], k: int) -> list[int]:
    if k == 0:
        return [0] * len(a)

    ranks = {value: i + 1 for i, value in enumerate(sorted(set(a)))}
    size = len(ranks)
    tree = [0] * (size + 1)
    result = []

    for i, value in enumerate(a):
        if i >= k:
            index = ranks[a[i - k]]
            while index <= size:
                tree[index] -= 1
                index += index & -index

        rank = ranks[value]
        index = rank
        not_taller = 0
        while index:
            not_taller += tree[index]
            index -= index & -index

        result.append(min(i, k) - not_taller)

        index = rank
        while index <= size:
            tree[index] += 1
            index += index & -index

    return result
